{
  "technical_and_design_decisions": [
    "All documentation will be built using MkDocs and hosted in the official Hyperledger Fabric docs repository, with versioned branches to separate v0.6 (stable) and v1.0 (development) content.",
    "The Node SDK will adhere to existing Fabric SDK interface design patterns (consistent with Go and Java SDKs) to ensure cross-language consistency for application developers.",
    "Ledger refactoring work will maintain backward compatibility with existing block data on Fabric networks, using the new block structure from merged gerrit change 2581 as the baseline.",
    "The invocation sanity check will be implemented as a pre-execution validation step in the peer's chaincode invocation pipeline to reject invalid invocations before processing.",
    "Demo materials for architecture/behavior walkthroughs will be designed to run against a local single-node Fabric v1.0 test network to eliminate external infrastructure dependencies."
  ],
  "assumptions": [
    "The FAB-687 API specification, gerrit changes 1795 (new channel config transaction) and 2581 (new block structure) are finalized and available for reference during development.",
    "The developer has full read/write access to all required Hyperledger Fabric repositories (core ledger, docs, SDK) and necessary local development environments.",
    "No additional third-party dependencies are required for the Node SDK beyond standard Node.js packages and existing Fabric core library interfaces.",
    "The existing Fabric v1.0 (sprint 6) codebase is buildable and runnable locally for testing all implemented changes and demo materials.",
    "Documentation redirects from legacy v0.6 links can be configured via the docs hosting platform without additional infrastructure work."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "New visitor onboarding documentation and navigation setup",
      "activity_description": "Create the getting started section of Fabric v1.0 docs including installation prerequisites, quick start sample app walkthrough, and organize documentation navigation to make core user and developer resources easily discoverable for new visitors.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "New channel configuration transaction documentation",
      "activity_description": "Document the full schema, fields, valid values, and example usage for the new channel creation configuration transaction as defined in FAB-687 and gerrit change 1795.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A3",
      "activity_name": "Peer and chaincode upgrade procedure documentation",
      "activity_description": "Create documentation for peer protocol upgrades without data loss, chaincode upgrades via the lifecycle system, applying patches via the SCC, and handling major protocol/security change migrations.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A4",
      "activity_name": "Ledger code and test refactoring",
      "activity_description": "Update all ledger core code and associated unit tests to use the new block structure from gerrit change 2581, fix test transaction construction logic, and remove explicit MSP security dependencies from ledger unit tests.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A5",
      "activity_name": "Fabric v1.0 architecture and behavior demo materials development",
      "activity_description": "Develop visual architecture diagrams of Fabric v1.0 (sprint 6 state), write executable demo scripts that showcase core network behavior, and create a walkthrough guide for collaborators and customers.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A6",
      "activity_name": "Versioned v1.0 documentation maintenance and v0.6 redirect setup",
      "activity_description": "Set up versioned documentation branches, configure redirects from legacy v0.6 documentation links to the stable v0.6 docs, create initial v1.0 usage documentation, and update content to align with ongoing v1.0 development.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A7",
      "activity_name": "Chaincode invocation sanity check implementation",
      "activity_description": "Add pre-processing validation logic to the peer's chaincode invocation handler to restrict invocations exclusively to the Lifecycle System Chaincode (LCCC) and normal user chaincode, and write unit tests to validate the check behavior.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A8",
      "activity_name": "Node.js SDK development for Fabric interaction",
      "activity_description": "Implement the Node SDK with core API methods for channel management, chaincode invocation/query, and event listening, aligned with existing Fabric SDK design patterns, and write SDK usage documentation and sample application code.",
      "most_likely_effort": 32
    }
  ],
  "reported_total": {
    "most_likely_effort": 136
  }
}

